#include <string.h>

static void reverse_string(char *str) {
    if (!str || !*str) return;
    char *start = str;
    char *end = str;
    while (*end) end++;
    end--; // Point to last non-null character
    while (start < end) {
        char temp = *start;
        *start = *end;
        *end = temp;
        start++;
        end--;
    }
}

int main(void) {
    static char buffer[200005];
    if (!fgets(buffer, sizeof(buffer), stdin)) return 0;
