static bool is_palindrome(const char *str) {
    int left = 0;
    int right = (int)strlen(str) - 1;
    // Skip newlines at the end
    while (right >= 0 && (str[right] == '\n' || str[right] == '\r')) {
        right--;
    }
    while (left < right) {
        while (left < right && !isalnum((unsigned char)str[left])) {
            left++;
        }
        while (left < right && !isalnum((unsigned char)str[right])) {
            right--;
        }
        if (tolower((unsigned char)str[left]) != tolower((unsigned char)str[right])) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}

int main(void) {
    static char buffer[200005];
    if (!fgets(buffer, sizeof(buffer), stdin)) {
        printf("true\n");
        return 0;
    }
    printf("%s\n", is_palindrome(buffer) ? "true" : "false");
    return 0;
}

