#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char ch;
    int count;
} CharFreq;

static int cmp_freq(const void *a, const void *b) {
    const CharFreq *ca = (const CharFreq *)a;
    const CharFreq *cb = (const CharFreq *)b;
    if (ca->count != cb->count) {
        return cb->count - ca->count; // Descending count
    }
    return (unsigned char)ca->ch - (unsigned char)cb->ch; // Ascending ASCII
}

int main(void) {
    static char buffer[200005];
    if (!fgets(buffer, sizeof(buffer), stdin)) return 0;
    int counts[256] = {0};
    for (int i = 0; buffer[i]; i++) {
        unsigned char c = (unsigned char)buffer[i];
        if (c > ' ' && c <= '~') {
            counts[c]++;
        }
    }
    CharFreq items[256];
    int num_items = 0;
    for (int i = 0; i < 256; i++) {
        if (counts[i] > 0) {
            items[num_items].ch = (char)i;
            items[num_items].count = counts[i];
            num_items++;
        }
    }
    qsort(items, num_items, sizeof(CharFreq), cmp_freq);
    for (int i = 0; i < num_items; i++) {
        printf("%c:%d%c", items[i].ch, items[i].count, (i == num_items - 1) ? '\n' : ' ');
    }
    return 0;
}

