    static char txt[200005], pat[200005];
    if (!fgets(txt, sizeof(txt), stdin)) return 0;
    if (!fgets(pat, sizeof(pat), stdin)) return 0;
    strip_newline(txt);
    strip_newline(pat);
    int n = (int)strlen(txt);
    int m = (int)strlen(pat);
    if (m == 0 || n < m) {
        printf("-1\n");
        return 0;
    }
    int *lps = (int *)malloc(m * sizeof(int));
    compute_lps(pat, m, lps);
    int i = 0, j = 0;
    int found = 0;
    while (i < n) {
        if (pat[j] == txt[i]) {
            i++;
            j++;
