static void expand(const char *s, int len, int left, int right, int *best_start, int *best_len) {
    while (left >= 0 && right < len && s[left] == s[right]) {
        left--;
        right++;
    }
    int cur_len = right - left - 1;
    int start = left + 1;
    if (cur_len > *best_len) {
        *best_len = cur_len;
        *best_start = start;
    }
}

int main(void) {
    static char buffer[5005];
    if (!fgets(buffer, sizeof(buffer), stdin)) return 0;
    int len = (int)strlen(buffer);
    while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r')) {
        buffer[--len] = '\0';
    }
    if (len == 0) return 0;
    int best_start = 0;
    int best_len = 1;
    for (int i = 0; i < len; i++) {
        // Odd length palindromes
        expand(buffer, len, i, i, &best_start, &best_len);
        // Even length palindromes
        expand(buffer, len, i, i + 1, &best_start, &best_len);
    }
    for (int i = 0; i < best_len; i++) {
        putchar(buffer[best_start + i]);
    }
    putchar('\n');
