#include <stdio.h>
#include <ctype.h>
#include <limits.h>

static int my_atoi(const char *str) {
    int i = 0;
    // Step 1: Skip leading whitespace
    while (str[i] && isspace((unsigned char)str[i])) {
        i++;
    }
    // Step 2: Sign check
    int sign = 1;
    if (str[i] == '+' || str[i] == '-') {
        if (str[i] == '-') sign = -1;
        i++;
    }
    // Step 3 & 4: Parse digits and check overflow
    long long result = 0;
    while (str[i] && isdigit((unsigned char)str[i])) {
        int digit = str[i] - '0';
        result = result * 10 + digit;
        if (sign == 1 && result > INT_MAX) {
            return INT_MAX;
        }
        if (sign == -1 && -result < INT_MIN) {
            return INT_MIN;
        }
        i++;
    }
    return (int)(sign * result);
}

int main(void) {
    static char buffer[200005];
    if (!fgets(buffer, sizeof(buffer), stdin)) return 0;
    printf("%d\n", my_atoi(buffer));
    return 0;
}
